driver_header:
#ifndef MCP23017_H
#define MCP23017_H

#include <stdint.h>
#include <stdbool.h>
#include <zephyr/device.h>

#include <zephyr/drivers/i2c.h>
struct device;

int mcp23017_init(const struct device *dev);
int mcp23017_read_porta(const struct device *dev, uint8_t *porta_byte);
int mcp23017_read_portb(const struct device *dev, uint8_t *portb_byte);

#endif /* MCP23017_H */

driver_source:
#include "mcp23017.h"
#include <errno.h>
#include <zephyr/drivers/i2c.h>

#include <zephyr/sys/byteorder.h>
#define MCP23017_I2C_ADDR 0x20

#define MCP23017_REG_IODIRA 0x00
#define MCP23017_REG_IODIRB 0x01
#define MCP23017_REG_GPIOA 0x12
#define MCP23017_REG_GPIOB 0x13

int mcp23017_init(const struct device *dev)
{
	if (!dev) {
		return -EINVAL;
	}

	const struct i2c_dt_spec spec = {
		.bus = dev,
		.addr = MCP23017_I2C_ADDR,
	};

	uint8_t buf[2];
	int ret;

	buf[0] = MCP23017_REG_IODIRA;
	buf[1] = 0x00;
	ret = i2c_write_dt(&spec, buf, 2);
	if (ret < 0) {
		return ret;
	}

	buf[0] = MCP23017_REG_IODIRB;
	buf[1] = 0x00;
	ret = i2c_write_dt(&spec, buf, 2);
	if (ret < 0) {
		return ret;
	}

	return 0;
}

int mcp23017_read_porta(const struct device *dev, uint8_t *porta_byte)
{
	if (!dev || !porta_byte) {
		return -EINVAL;
	}

	const struct i2c_dt_spec spec = {
		.bus = dev,
		.addr = MCP23017_I2C_ADDR,
	};

	uint8_t reg = MCP23017_REG_GPIOA;
	int ret = i2c_write_dt(&spec, &reg, 1);
	if (ret < 0) {
		return ret;
	}

	ret = i2c_read_dt(&spec, porta_byte, 1);
	if (ret < 0) {
		return ret;
	}

	return 0;
}

int mcp23017_read_portb(const struct device *dev, uint8_t *portb_byte)
{
	if (!dev || !portb_byte) {
		return -EINVAL;
	}

	const struct i2c_dt_spec spec = {
		.bus = dev,
		.addr = MCP23017_I2C_ADDR,
	};

	uint8_t reg = MCP23017_REG_GPIOB;
	int ret = i2c_write_dt(&spec, &reg, 1);
	if (ret < 0) {
		return ret;
	}

	ret = i2c_read_dt(&spec, portb_byte, 1);
	if (ret < 0) {
		return ret;
	}

	return 0;
}

